'use client';

import { useMemo } from 'react';

import { Button } from '@/registry/ndeko/ui/button';

import { DemoBand } from './_parts/demo-band';
import { AT_REST, NEXT_FRAME } from './_parts/frame-loop';
import { DEFAULT_HUE, useHueCycle } from './_parts/hue';
import {
  clamp,
  dampingOf,
  smoothstep,
  springSpeedOf,
  type Point,
} from './_parts/math';
import type { Scene } from './_parts/stage';
import { StageCanvas } from './_parts/stage-canvas';
import { wipeSurface, type Inks, type Surface } from './_parts/surface';

const DEFAULT_PITCH = 20;

const MIN_PITCH = 10;

/**
 * A cube stands half a pitch at most. At that height it reaches the edge of its own cell and no
 * further, so one cube is wiped and drawn again without touching a neighbour.
 */
const MAX_HEIGHT_SHARE = 0.5;

const REST_HEIGHT_SHARE = 0.1;

/** How far above its base the cell of a cube starts, as a share of the pitch. */
const CELL_ABOVE_SHARE = 0.75;

const POINTER_REACH_PX = 120;

const STIFFNESS = 150;

const DAMPING = dampingOf(STIFFNESS);

const SETTLED_PX = 0.02;

/** A cube is drawn again once it has moved this far from where it was last drawn. */
const REDRAW_PX = 0.08;

const WAVE_SPEED_PX = 240;

const WAVE_WIDTH_PX = 72;

/** Past this many widths from its crest the wave lifts nothing. */
const WAVE_REACH = 3;

const WAVE_MARGIN_PX = WAVE_WIDTH_PX * WAVE_REACH;

/** The idle wave lifts a cube to this share of what the pointer does. */
const WAVE_SHARE = 0.55;

const WAVE_PAUSE_MS = 2200;

/** The wave crosses the field at twenty degrees from the horizontal. */
const WAVE_ACROSS = 0.94;

const WAVE_DOWN = 0.34;

const LEFT_ALPHA = 0.1;

const RIGHT_ALPHA = 0.17;

const TOP_ALPHA = 0.06;

/** The hue a top wears at full height. Text sits above the field, so it stays a tint. */
const TOP_HUE_ALPHA = 0.55;

const MIN_LIFT = 0.02;

/** Where the cubes stand risen in the still picture, across and down the box. */
const STILL_AT: Point = { x: 0.7, y: 0.42 };

const NO_INKS: Inks = { hue: 'transparent', line: 'transparent' };

type CubeField = {
  pitch: number;
  half: number;
  halfWidth: number;
  halfDepth: number;
  restHeight: number;
  maxRise: number;
  isStill: boolean;
  inks: Inks;
  count: number;
  centreX: Float32Array;
  centreY: Float32Array;
  /** How far along the path of the wave each cube sits. */
  along: Float32Array;
  rise: Float32Array;
  speed: Float32Array;
  drawn: Float32Array;
  pointer: Point;
  hasPointer: boolean;
  isWaving: boolean;
  waveFront: number;
  waveEnd: number;
  nextWaveAt: number;
};

function fieldOf(size: number): CubeField {
  const pitch = Math.max(MIN_PITCH, size);
  const half = pitch / 2;
  const halfWidth = half - 1;
  const halfDepth = halfWidth / 2;
  const maxHeight = pitch * MAX_HEIGHT_SHARE;
  const restHeight = pitch * REST_HEIGHT_SHARE;
  const maxRise = maxHeight - restHeight;
  return {
    pitch,
    half,
    halfWidth,
    halfDepth,
    restHeight,
    maxRise,
    isStill: false,
    inks: NO_INKS,
    count: 0,
    centreX: new Float32Array(0),
    centreY: new Float32Array(0),
    along: new Float32Array(0),
    rise: new Float32Array(0),
    speed: new Float32Array(0),
    drawn: new Float32Array(0),
    pointer: { x: 0, y: 0 },
    hasPointer: false,
    isWaving: false,
    waveFront: 0,
    waveEnd: 0,
    nextWaveAt: 0,
  };
}

function bumpOf(field: CubeField, index: number, pointer: Point) {
  const offsetX = field.centreX[index] - pointer.x;
  const offsetY = field.centreY[index] - pointer.y;
  const isFarAcross = Math.abs(offsetX) > POINTER_REACH_PX;
  const isFarDown = Math.abs(offsetY) > POINTER_REACH_PX;
  if (isFarAcross || isFarDown) {
    return 0;
  }
  const distance = Math.hypot(offsetX, offsetY);
  const nearness = smoothstep(POINTER_REACH_PX, 0, distance);
  return nearness * field.maxRise;
}

function waveOf(field: CubeField, index: number) {
  const behind = field.along[index] - field.waveFront;
  const reach = behind / WAVE_WIDTH_PX;
  const isOutOfReach = Math.abs(reach) > WAVE_REACH;
  if (isOutOfReach) {
    return 0;
  }
  const squared = reach * reach;
  const ridge = Math.exp(-squared);
  const lift = ridge * WAVE_SHARE;
  return lift * field.maxRise;
}

function targetOf(field: CubeField, index: number) {
  let target = 0;
  if (field.hasPointer) {
    target += bumpOf(field, index, field.pointer);
  }
  if (field.isWaving) {
    target += waveOf(field, index);
  }
  return Math.min(target, field.maxRise);
}

/** The still picture: the cubes stand as if a pointer rested on them. */
function poseStill(field: CubeField, surface: Surface) {
  const x = surface.width * STILL_AT.x;
  const y = surface.height * STILL_AT.y;
  const pointer = { x, y };
  for (let index = 0; index < field.count; index += 1) {
    field.rise[index] = bumpOf(field, index, pointer);
  }
}

/**
 * Cubes sit on every other crossing of a grid one pitch wide and half a pitch tall, so their cells
 * tile the box: each cube owns a square of one pitch that no other cube enters.
 */
function layCubes(field: CubeField, surface: Surface, isStill: boolean) {
  const { pitch, half } = field;
  const columns = Math.ceil(surface.width / pitch) + 2;
  const rows = Math.ceil(surface.height / half) + 3;
  const capacity = columns * rows;
  const across = surface.width * WAVE_ACROSS;
  const down = surface.height * WAVE_DOWN;
  field.centreX = new Float32Array(capacity);
  field.centreY = new Float32Array(capacity);
  field.along = new Float32Array(capacity);
  field.rise = new Float32Array(capacity);
  field.speed = new Float32Array(capacity);
  field.drawn = new Float32Array(capacity);
  let count = 0;
  for (let row = 0; row < rows; row += 1) {
    const firstColumn = row % 2;
    for (let column = firstColumn; column < columns; column += 2) {
      const x = column * pitch;
      const y = row * half;
      const alongX = x * WAVE_ACROSS;
      const alongY = y * WAVE_DOWN;
      field.centreX[count] = x;
      field.centreY[count] = y;
      field.along[count] = alongX + alongY;
      count += 1;
    }
  }
  field.count = count;
  field.isStill = isStill;
  field.hasPointer = false;
  field.waveEnd = across + down + WAVE_MARGIN_PX;
  if (isStill) {
    poseStill(field, surface);
  }
}

function traceLeft(
  pen: CanvasRenderingContext2D,
  field: CubeField,
  index: number
) {
  const x = field.centreX[index];
  const base = field.centreY[index];
  const height = field.restHeight + field.rise[index];
  const top = base - height;
  const left = x - field.halfWidth;
  const topFront = top + field.halfDepth;
  const baseFront = base + field.halfDepth;
  pen.moveTo(left, top);
  pen.lineTo(x, topFront);
  pen.lineTo(x, baseFront);
  pen.lineTo(left, base);
  pen.closePath();
}

function traceRight(
  pen: CanvasRenderingContext2D,
  field: CubeField,
  index: number
) {
  const x = field.centreX[index];
  const base = field.centreY[index];
  const height = field.restHeight + field.rise[index];
  const top = base - height;
  const right = x + field.halfWidth;
  const topFront = top + field.halfDepth;
  const baseFront = base + field.halfDepth;
  pen.moveTo(x, topFront);
  pen.lineTo(right, top);
  pen.lineTo(right, base);
  pen.lineTo(x, baseFront);
  pen.closePath();
}

function traceTop(
  pen: CanvasRenderingContext2D,
  field: CubeField,
  index: number
) {
  const x = field.centreX[index];
  const height = field.restHeight + field.rise[index];
  const top = field.centreY[index] - height;
  const back = top - field.halfDepth;
  const front = top + field.halfDepth;
  const left = x - field.halfWidth;
  const right = x + field.halfWidth;
  pen.moveTo(x, back);
  pen.lineTo(right, top);
  pen.lineTo(x, front);
  pen.lineTo(left, top);
  pen.closePath();
}

type FaceTracer = typeof traceLeft;

/** The top takes the hue as the cube rises: the neutral says floor, the hue says lifted. */
function tintTop(
  pen: CanvasRenderingContext2D,
  field: CubeField,
  index: number
) {
  const lift = field.rise[index] / field.maxRise;
  if (lift < MIN_LIFT) {
    return;
  }
  pen.fillStyle = field.inks.hue;
  pen.globalAlpha = lift * TOP_HUE_ALPHA;
  pen.beginPath();
  traceTop(pen, field, index);
  pen.fill();
}

function fillFace(
  pen: CanvasRenderingContext2D,
  field: CubeField,
  index: number,
  alpha: number,
  trace: FaceTracer
) {
  pen.globalAlpha = alpha;
  pen.beginPath();
  trace(pen, field, index);
  pen.fill();
}

/** One cube, in its own cell: the cell is wiped, then the three faces are drawn where it now stands. */
function paintCube(
  pen: CanvasRenderingContext2D,
  field: CubeField,
  index: number
) {
  const cellLeft = field.centreX[index] - field.half;
  const cellAbove = field.pitch * CELL_ABOVE_SHARE;
  const cellTop = field.centreY[index] - cellAbove;
  pen.globalAlpha = 1;
  pen.clearRect(cellLeft, cellTop, field.pitch, field.pitch);
  pen.fillStyle = field.inks.line;
  fillFace(pen, field, index, LEFT_ALPHA, traceLeft);
  fillFace(pen, field, index, RIGHT_ALPHA, traceRight);
  fillFace(pen, field, index, TOP_ALPHA, traceTop);
  tintTop(pen, field, index);
  field.drawn[index] = field.rise[index];
}

/** The same face of every cube in one fill: cubes never overlap, so one path holds them all. */
function fillFaces(
  pen: CanvasRenderingContext2D,
  field: CubeField,
  alpha: number,
  trace: FaceTracer
) {
  pen.globalAlpha = alpha;
  pen.beginPath();
  for (let index = 0; index < field.count; index += 1) {
    trace(pen, field, index);
  }
  pen.fill();
}

function drawCubes(field: CubeField, surface: Surface) {
  const { pen } = surface;
  wipeSurface(surface);
  pen.fillStyle = field.inks.line;
  fillFaces(pen, field, LEFT_ALPHA, traceLeft);
  fillFaces(pen, field, RIGHT_ALPHA, traceRight);
  fillFaces(pen, field, TOP_ALPHA, traceTop);
  for (let index = 0; index < field.count; index += 1) {
    tintTop(pen, field, index);
  }
  field.drawn.set(field.rise);
}

/** A wave crosses the field, then the field rests for a while before the next one. */
function advanceWave(field: CubeField, seconds: number, now: number) {
  if (!field.isWaving) {
    const isDue = now >= field.nextWaveAt;
    if (isDue) {
      field.isWaving = true;
      field.waveFront = -WAVE_MARGIN_PX;
    }
    return;
  }
  field.waveFront += WAVE_SPEED_PX * seconds;
  const hasCrossed = field.waveFront > field.waveEnd;
  if (hasCrossed) {
    field.isWaving = false;
    field.nextWaveAt = now + WAVE_PAUSE_MS;
  }
}

/** Moves one cube towards its target on a spring that does not bounce. It answers whether it still moves. */
function moveCube(field: CubeField, index: number, seconds: number) {
  const target = targetOf(field, index);
  const gap = target - field.rise[index];
  const speed = springSpeedOf(
    gap,
    field.speed[index],
    STIFFNESS,
    DAMPING,
    seconds
  );
  const isClose = Math.abs(gap) < SETTLED_PX;
  const isSlow = Math.abs(speed) < SETTLED_PX;
  if (isClose && isSlow) {
    field.rise[index] = target;
    field.speed[index] = 0;
    return false;
  }
  const travel = speed * seconds;
  const moved = field.rise[index] + travel;
  field.rise[index] = clamp(moved, 0, field.maxRise);
  field.speed[index] = speed;
  return true;
}

/** Only the cubes that moved are drawn again. With nothing moving, the loop sleeps until the next wave is due. */
function stepCubes(
  field: CubeField,
  surface: Surface,
  seconds: number,
  now: number
) {
  if (field.isStill) {
    return AT_REST;
  }
  advanceWave(field, seconds, now);
  let isMoving = false;
  for (let index = 0; index < field.count; index += 1) {
    const stillMoves = moveCube(field, index, seconds);
    const change = field.rise[index] - field.drawn[index];
    const isStale = Math.abs(change) > REDRAW_PX;
    if (isStale) {
      paintCube(surface.pen, field, index);
    }
    isMoving = isMoving || stillMoves;
  }
  if (isMoving || field.isWaving) {
    return NEXT_FRAME;
  }
  const untilWave = field.nextWaveAt - now;
  return Math.max(NEXT_FRAME, untilWave);
}

function createCubeScene(size: number): Scene {
  const field = fieldOf(size);
  return {
    ink(inks) {
      field.inks = inks;
    },
    fit(surface, isStill) {
      layCubes(field, surface, isStill);
    },
    draw(surface) {
      drawCubes(field, surface);
    },
    step(surface, seconds, now) {
      return stepCubes(field, surface, seconds, now);
    },
    pointerMoved(x, y) {
      field.pointer.x = x;
      field.pointer.y = y;
      field.hasPointer = true;
    },
    pointerLeft() {
      field.hasPointer = false;
    },
  };
}

export type CubeFieldProps = {
  className?: string;
  /** Any colour token, such as `var(--primary)` or `var(--series-2)`. A cube takes it as it rises. */
  hue?: string;
  /** The distance between two cubes, in pixels. */
  size?: number;
  /** Cubes rise under the pointer. Without it, only the idle wave crosses the field. */
  interactive?: boolean;
};

/**
 * A floor of small isometric cubes on one canvas. They rise under the pointer, each on its own
 * spring, and a slow wave crosses them while nobody touches them. Only the cubes that move are
 * drawn again, and nothing is drawn while they rest. It fills its parent, which must be
 * positioned. Under reduced motion the cubes stand still.
 */
export function CubeField({
  className,
  hue = DEFAULT_HUE,
  size = DEFAULT_PITCH,
  interactive = true,
}: CubeFieldProps) {
  const scene = useMemo(() => createCubeScene(size), [size]);

  return (
    <StageCanvas
      scene={scene}
      hue={hue}
      isInteractive={interactive}
      className={className}
    />
  );
}

export default function Background02() {
  const { hue, nextHue } = useHueCycle();

  return (
    <DemoBand
      title='A floor of cubes that rises under the pointer'
      background={<CubeField hue={hue} />}
    >
      <Button onClick={nextHue}>Change hue</Button>
    </DemoBand>
  );
}

import { useId, type ReactNode, type Ref } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

type BandAlign = 'center' | 'end';

const ALIGNMENTS: Record<BandAlign, string> = {
  center: 'justify-center',
  end: 'justify-end pb-10',
};

type DemoBandProps = {
  ref?: Ref<HTMLElement>;
  title: string;
  /** The background under test. It fills the band, behind the headline and the actions. */
  background: ReactNode;
  /** `end` sets the headline at the foot of the band and leaves its middle to the background. */
  align?: BandAlign;
  children: ReactNode;
};

/**
 * The band every background is shown in: the page colour, a headline in the foreground colour and
 * the actions laid straight over the background, to prove that text stays readable above it.
 */
export function DemoBand({
  ref,
  title,
  background,
  align = 'center',
  children,
}: DemoBandProps) {
  const titleId = useId();

  return (
    <section
      ref={ref}
      aria-labelledby={titleId}
      className={cn(
        'bg-background @container relative isolate flex h-90 w-full flex-col items-center overflow-hidden rounded-xl',
        ALIGNMENTS[align]
      )}
    >
      {background}
      <div className='relative flex max-w-lg flex-col items-center gap-5 px-6 text-center'>
        <h3
          id={titleId}
          className='text-2xl font-semibold text-balance @lg:text-3xl'
        >
          {title}
        </h3>
        <div className='flex flex-wrap items-center justify-center gap-2'>
          {children}
        </div>
      </div>
    </section>
  );
}

const FRAMES_PER_SECOND = 30;

const FRAME_MS = 1000 / FRAMES_PER_SECOND;

/**
 * The timer between two frames ends this long before the next one is due, so the frame it asks for
 * lands on the screen refresh that is due and not on the one after.
 */
const REFRESH_LEAD_MS = 5;

const TIMER_MS = FRAME_MS - REFRESH_LEAD_MS;

/** A frame that comes late, after a long task, moves the picture no further than this long would. */
const MAX_STEP_S = 0.05;

/** What a frame answers while the picture still moves: the next one comes as soon as the cap allows. */
export const NEXT_FRAME = 0;

/** What a frame answers once the picture has come to rest: nothing is asked for until `wake`. */
export const AT_REST = Number.POSITIVE_INFINITY;

/** Draws one frame, `seconds` after the last one, and answers how many milliseconds it can wait for the next. */
export type FrameHandler = (seconds: number, now: number) => number;

export type FrameLoop = {
  start: () => void;
  stop: () => void;
  wake: () => void;
};

/**
 * Frames at thirty a second at most. Between two frames there is one timer and no animation frame,
 * so a 120 Hz screen does not run four rounds of main-thread work for one frame drawn. Stopped or
 * at rest, the loop holds no timer and asks for no frame.
 */
export function createFrameLoop(onFrame: FrameHandler): FrameLoop {
  let frame = 0;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let isStarted = false;
  let lastFrameAt = 0;

  function clearPending() {
    cancelAnimationFrame(frame);
    clearTimeout(timer);
    frame = 0;
    timer = undefined;
  }

  function askForFrame() {
    timer = undefined;
    frame = requestAnimationFrame(tick);
  }

  function schedule(wait: number) {
    clearPending();
    const now = performance.now();
    const sinceFrame = now - lastFrameAt;
    const untilCap = TIMER_MS - sinceFrame;
    const delay = Math.max(wait, untilCap);
    if (delay <= 0) {
      askForFrame();
      return;
    }
    timer = setTimeout(askForFrame, delay);
  }

  function tick(now: number) {
    frame = 0;
    const elapsedMs = now - lastFrameAt;
    const elapsed = elapsedMs / 1000;
    const forward = Math.max(0, elapsed);
    const seconds = Math.min(forward, MAX_STEP_S);
    lastFrameAt = now;
    const wait = onFrame(seconds, now);
    const isResting = wait === AT_REST;
    if (isResting || !isStarted) {
      return;
    }
    schedule(wait);
  }

  function start() {
    if (isStarted) {
      return;
    }
    const now = performance.now();
    isStarted = true;
    lastFrameAt = now - FRAME_MS;
    schedule(NEXT_FRAME);
  }

  function stop() {
    isStarted = false;
    clearPending();
  }

  function wake() {
    const isFrameComing = frame !== 0;
    if (!isStarted || isFrameComing) {
      return;
    }
    schedule(NEXT_FRAME);
  }

  return { start, stop, wake };
}

'use client';

import { useState } from 'react';

/** A background wears one hue: the brand unless it is told otherwise. */
export const DEFAULT_HUE = 'var(--primary)';

/** The brand first, then the series hues that differ from it. */
const DEMO_HUES = [
  DEFAULT_HUE,
  'var(--series-2)',
  'var(--series-3)',
  'var(--series-4)',
  'var(--series-5)',
];

/** The hue of a demo, and the step to the next one, to show a background in each hue it accepts. */
export function useHueCycle() {
  const [index, setIndex] = useState(0);
  const hue = DEMO_HUES[index] ?? DEFAULT_HUE;

  function nextHue() {
    setIndex((current) => {
      const next = current + 1;
      return next % DEMO_HUES.length;
    });
  }

  return { hue, nextHue };
}

export type Point = {
  x: number;
  y: number;
};

export function clamp(value: number, low: number, high: number) {
  const raised = Math.max(low, value);
  return Math.min(high, raised);
}

/** How much of the way left is covered in `seconds`: the same glide whatever the frame rate. */
export function shareOf(seconds: number, easeSeconds: number) {
  const ratio = seconds / easeSeconds;
  const decay = Math.exp(-ratio);
  return 1 - decay;
}

export function towards(from: number, to: number, share: number) {
  const gap = to - from;
  const step = gap * share;
  return from + step;
}

/** From 0 at `low` to 1 at `high`, leaving and arriving without a corner. */
export function smoothstep(low: number, high: number, value: number) {
  const span = high - low;
  const offset = value - low;
  const raw = offset / span;
  const share = clamp(raw, 0, 1);
  const doubled = 2 * share;
  const curve = 3 - doubled;
  const squared = share * share;
  return squared * curve;
}

/** The damping that brings a spring of this stiffness to its target without passing it. */
export function dampingOf(stiffness: number) {
  const root = Math.sqrt(stiffness);
  return 2 * root;
}

/**
 * The speed of a spring one step later. The caller then moves the value by that speed over the
 * same step, so the value follows its target and settles on it.
 */
export function springSpeedOf(
  gap: number,
  speed: number,
  stiffness: number,
  damping: number,
  seconds: number
) {
  const pull = gap * stiffness;
  const drag = speed * damping;
  const push = pull - drag;
  const gain = push * seconds;
  return speed + gain;
}

import type { Point } from './math';

/**
 * Where a point of the window falls inside `host`, in the pixels of its own box, or null when it
 * falls outside. A host that an ancestor scales still answers in its own pixels.
 */
export function placeIn(
  host: HTMLElement,
  clientX: number,
  clientY: number
): Point | null {
  const box = host.getBoundingClientRect();
  const isEmpty = box.width === 0 || box.height === 0;
  if (isEmpty) {
    return null;
  }
  const isInsideX = clientX >= box.left && clientX <= box.right;
  const isInsideY = clientY >= box.top && clientY <= box.bottom;
  if (!isInsideX || !isInsideY) {
    return null;
  }
  const scaleX = host.offsetWidth / box.width;
  const scaleY = host.offsetHeight / box.height;
  const offsetX = clientX - box.left;
  const offsetY = clientY - box.top;
  const x = offsetX * scaleX;
  const y = offsetY * scaleY;
  return { x, y };
}

/** Where the centre of `element` falls inside `host`, or null when it falls outside. */
export function centreIn(host: HTMLElement, element: Element) {
  const box = element.getBoundingClientRect();
  const halfWidth = box.width / 2;
  const halfHeight = box.height / 2;
  const centreX = box.left + halfWidth;
  const centreY = box.top + halfHeight;
  return placeIn(host, centreX, centreY);
}

/**
 * Follows a pointer that can hover, from the window: content laid over a background takes the
 * pointer events of its own box, so a listener on the background would go blind under a headline.
 * The place is read once a frame at most, and only on a frame where the pointer moved. `onMove`
 * gets the place inside `host`; `onLeave` is called once when the pointer goes out of it. The
 * function returned ends the watch, and lets go of a pointer that was still over the host.
 */
export function watchPointer(
  host: HTMLElement,
  onMove: (x: number, y: number) => void,
  onLeave: () => void
) {
  let clientX = 0;
  let clientY = 0;
  let frame = 0;
  let isOver = false;

  function leave() {
    if (!isOver) {
      return;
    }
    isOver = false;
    onLeave();
  }

  function read() {
    frame = 0;
    const place = placeIn(host, clientX, clientY);
    if (!place) {
      leave();
      return;
    }
    isOver = true;
    onMove(place.x, place.y);
  }

  function onPointerMove(event: PointerEvent) {
    const isTouch = event.pointerType === 'touch';
    if (isTouch) {
      return;
    }
    clientX = event.clientX;
    clientY = event.clientY;
    const isReadComing = frame !== 0;
    if (isReadComing) {
      return;
    }
    frame = requestAnimationFrame(read);
  }

  function onPointerGone() {
    cancelAnimationFrame(frame);
    frame = 0;
    leave();
  }

  const root = document.documentElement;
  window.addEventListener('pointermove', onPointerMove, { passive: true });
  root.addEventListener('pointerleave', onPointerGone, { passive: true });

  return () => {
    window.removeEventListener('pointermove', onPointerMove);
    root.removeEventListener('pointerleave', onPointerGone);
    onPointerGone();
  };
}

/**
 * A background sits behind content for as long as the page is open, so everything it runs hangs on
 * this answer: its box touches the screen and the tab is the one looked at. `onChange` is called
 * each time the answer changes, starting from "not showing". The function returned ends the watch.
 */
export function watchShowing(
  element: Element,
  onChange: (isShowing: boolean) => void
) {
  let isOnScreen = false;
  let wasShowing = false;

  function report() {
    const isTabShown = document.visibilityState === 'visible';
    const isShowing = isOnScreen && isTabShown;
    if (isShowing === wasShowing) {
      return;
    }
    wasShowing = isShowing;
    onChange(isShowing);
  }

  function onCrossing(entries: IntersectionObserverEntry[]) {
    const latest = entries.at(-1);
    if (!latest) {
      return;
    }
    isOnScreen = latest.isIntersecting;
    report();
  }

  const observer = new IntersectionObserver(onCrossing);
  observer.observe(element);
  document.addEventListener('visibilitychange', report);

  return () => {
    observer.disconnect();
    document.removeEventListener('visibilitychange', report);
  };
}

'use client';

import { useEffect, useImperativeHandle, useRef, type Ref } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';

import type { Point } from './math';
import { mountStage, type Scene, type Stage } from './stage';

export type StageHandle = {
  /** Something outside the loop changed the scene: it is drawn again, and its loop is woken. */
  refresh: () => void;
  /** Where the centre of an element sits on the canvas, or null when it is outside. */
  centreOf: (element: Element) => Point | null;
};

type StageCanvasProps = {
  scene: Scene;
  hue: string;
  isInteractive?: boolean;
  className?: string;
  handleRef?: Ref<StageHandle>;
};

/**
 * The one canvas of a background. It fills its parent, lets every pointer event through and is
 * hidden from assistive technology, since it is decoration. A canvas cannot take a colour from a
 * class: the hue rides on its `color` and the neutral of lines on `decoration-foreground`, and the
 * stage reads both from the computed style. No transition may sit on those two, or the stage
 * would read a colour halfway through it.
 */
export function StageCanvas({
  scene,
  hue,
  isInteractive = false,
  className,
  handleRef,
}: StageCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const stage = useRef<Stage | null>(null);
  const shouldReduceMotion = usePrefersReducedMotion();

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) {
      return;
    }
    const mounted = mountStage(canvas, scene, {
      isStill: shouldReduceMotion,
      isInteractive,
    });
    stage.current = mounted;
    return () => {
      mounted?.dispose();
      stage.current = null;
    };
  }, [scene, isInteractive, shouldReduceMotion]);

  useEffect(() => {
    stage.current?.reink();
  }, [hue]);

  useImperativeHandle(
    handleRef,
    () => ({
      refresh: () => stage.current?.refresh(),
      centreOf: (element) => stage.current?.centreOf(element) ?? null,
    }),
    []
  );

  return (
    <canvas
      ref={canvasRef}
      aria-hidden='true'
      style={{ color: hue }}
      className={cn(
        'decoration-foreground pointer-events-none absolute inset-0 size-full',
        className
      )}
    />
  );
}

import { createFrameLoop } from './frame-loop';
import type { Point } from './math';
import { centreIn, watchPointer } from './pointer';
import { watchShowing } from './showing';
import {
  createSurface,
  fitSurface,
  hasSameInks,
  inksOf,
  isFitted,
  watchSurface,
  type Inks,
  type Surface,
} from './surface';

/** What a background draws on its canvas. The stage decides when; the scene only knows how. */
export type Scene = {
  /** The colours changed: the theme, or the hue. */
  ink: (inks: Inks) => void;
  /**
   * The box changed, and the canvas was wiped: what depends on its size is built again. `isStill`
   * is the reduced motion setting: the scene then holds its most telling picture and never moves.
   */
  fit: (surface: Surface, isStill: boolean) => void;
  /** The whole picture as it stands. */
  draw: (surface: Surface) => void;
  /**
   * Moves the picture on by `seconds` and draws what changed. It answers how long it can wait for
   * its next frame: `NEXT_FRAME`, `AT_REST`, or a number of milliseconds.
   */
  step: (surface: Surface, seconds: number, now: number) => number;
  pointerMoved?: (x: number, y: number) => void;
  pointerLeft?: () => void;
};

export type Stage = {
  /** Something outside the loop changed the scene: it is drawn again, and its loop is woken. */
  refresh: () => void;
  /** Reads the colours again, and draws again when they changed. */
  reink: () => void;
  /** Where the centre of an element sits on the canvas, or null when it is outside. */
  centreOf: (element: Element) => Point | null;
  dispose: () => void;
};

export type StageOptions = {
  /** Reduced motion: no pointer is followed and nothing moves by itself. */
  isStill: boolean;
  isInteractive: boolean;
};

function idle() {}

function stageOf(
  surface: Surface,
  scene: Scene,
  { isStill, isInteractive }: StageOptions
): Stage {
  const { canvas } = surface;
  const followsPointer = isInteractive && !isStill;
  let isShowing = false;
  let stopPointer = idle;
  let inks = inksOf(canvas);

  const loop = createFrameLoop((seconds, now) =>
    scene.step(surface, seconds, now)
  );

  function wake() {
    if (isShowing) {
      loop.wake();
    }
  }

  function lay() {
    fitSurface(surface);
    scene.fit(surface, isStill);
    scene.draw(surface);
  }

  function onPointerMove(x: number, y: number) {
    scene.pointerMoved?.(x, y);
    wake();
  }

  function onPointerLeave() {
    scene.pointerLeft?.();
    wake();
  }

  function show() {
    isShowing = true;
    if (followsPointer) {
      stopPointer = watchPointer(canvas, onPointerMove, onPointerLeave);
    }
    loop.start();
  }

  function hide() {
    isShowing = false;
    stopPointer();
    stopPointer = idle;
    loop.stop();
  }

  function onShowing(isNowShowing: boolean) {
    if (isNowShowing) {
      show();
      return;
    }
    hide();
  }

  function onResize() {
    if (isFitted(surface)) {
      return;
    }
    lay();
    wake();
  }

  function reink() {
    const latest = inksOf(canvas);
    if (hasSameInks(inks, latest)) {
      return;
    }
    inks = latest;
    scene.ink(inks);
    scene.draw(surface);
    wake();
  }

  /** In the loop, the next frame draws the change. Out of it, nothing would, so it is drawn here. */
  function refresh() {
    const isOutOfLoop = isStill || !isShowing;
    if (isOutOfLoop) {
      scene.draw(surface);
    }
    wake();
  }

  scene.ink(inks);
  lay();
  const stopSurface = watchSurface(canvas, onResize, reink);
  const stopShowing = watchShowing(canvas, onShowing);

  return {
    refresh,
    reink,
    centreOf: (element) => centreIn(canvas, element),
    dispose() {
      stopShowing();
      stopSurface();
      hide();
    },
  };
}

/**
 * Puts a scene on a canvas. The stage sizes the canvas for the screen, reads its colours, and runs
 * the loop of the scene only while the canvas is on screen in a visible tab. It draws one frame
 * when it is set up, so the picture is there before anything moves.
 */
export function mountStage(
  canvas: HTMLCanvasElement,
  scene: Scene,
  options: StageOptions
) {
  const surface = createSurface(canvas);
  if (!surface) {
    return null;
  }
  return stageOf(surface, scene, options);
}

/** A backing store above two device pixels a point costs four times the fill for a picture nobody sees sharper. */
const MAX_PIXEL_RATIO = 2;

const THEME_WATCH = {
  attributes: true,
  attributeFilter: ['class', 'data-theme'],
};

const DARK_SCHEME = '(prefers-color-scheme: dark)';

export type Surface = {
  canvas: HTMLCanvasElement;
  pen: CanvasRenderingContext2D;
  /** The box of the canvas in CSS pixels: one unit drawn is one of them, whatever the screen. */
  width: number;
  height: number;
  pixelRatio: number;
};

export type Inks = {
  /** The hue of the background, resolved by the browser for the current theme. */
  hue: string;
  /** The neutral of lines: the foreground of the theme. */
  line: string;
};

export function createSurface(canvas: HTMLCanvasElement): Surface | null {
  const pen = canvas.getContext('2d');
  if (!pen) {
    return null;
  }
  return { canvas, pen, width: 0, height: 0, pixelRatio: 1 };
}

function pixelRatioOf() {
  const devicePixelRatio = window.devicePixelRatio || 1;
  return Math.min(devicePixelRatio, MAX_PIXEL_RATIO);
}

/** Sizes the backing store to the box of the canvas and to the screen. It also wipes the canvas. */
export function fitSurface(surface: Surface) {
  const { canvas, pen } = surface;
  const pixelRatio = pixelRatioOf();
  const width = canvas.clientWidth;
  const height = canvas.clientHeight;
  const deviceWidth = width * pixelRatio;
  const deviceHeight = height * pixelRatio;
  surface.width = width;
  surface.height = height;
  surface.pixelRatio = pixelRatio;
  canvas.width = Math.round(deviceWidth);
  canvas.height = Math.round(deviceHeight);
  pen.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
}

export function isFitted(surface: Surface) {
  const { canvas } = surface;
  const hasWidth = surface.width === canvas.clientWidth;
  const hasHeight = surface.height === canvas.clientHeight;
  const hasRatio = surface.pixelRatio === pixelRatioOf();
  const hasSize = hasWidth && hasHeight;
  return hasSize && hasRatio;
}

export function wipeSurface(surface: Surface) {
  surface.pen.globalAlpha = 1;
  surface.pen.clearRect(0, 0, surface.width, surface.height);
}

/**
 * A canvas cannot take a colour from a class, so it reads its colours from its own computed style,
 * where the browser has already resolved the tokens for the current theme. The hue rides on
 * `color` and the neutral of lines on `text-decoration-color`, which paints nothing on a canvas.
 */
export function inksOf(canvas: HTMLCanvasElement): Inks {
  const style = getComputedStyle(canvas);
  return { hue: style.color, line: style.textDecorationColor };
}

export function hasSameInks(first: Inks, second: Inks) {
  const hasSameHue = first.hue === second.hue;
  const hasSameLine = first.line === second.line;
  return hasSameHue && hasSameLine;
}

function densityQueryOf() {
  return `(resolution: ${window.devicePixelRatio}dppx)`;
}

/**
 * Calls `onResize` when the box of the canvas or the density of the screen changes, and `onTheme`
 * when the page may have changed theme: a class or an attribute on the root or the body, or the
 * system setting. The function returned ends the watch.
 */
export function watchSurface(
  canvas: HTMLCanvasElement,
  onResize: () => void,
  onTheme: () => void
) {
  const sizeObserver = new ResizeObserver(() => onResize());
  const themeObserver = new MutationObserver(() => onTheme());
  const scheme = window.matchMedia(DARK_SCHEME);
  let density = window.matchMedia(densityQueryOf());

  function onScheme() {
    onTheme();
  }

  /** The query names one density: once the screen has left it, a new query watches the next one. */
  function onDensity() {
    density.removeEventListener('change', onDensity);
    density = window.matchMedia(densityQueryOf());
    density.addEventListener('change', onDensity);
    onResize();
  }

  sizeObserver.observe(canvas);
  themeObserver.observe(document.documentElement, THEME_WATCH);
  themeObserver.observe(document.body, THEME_WATCH);
  scheme.addEventListener('change', onScheme);
  density.addEventListener('change', onDensity);

  return () => {
    sizeObserver.disconnect();
    themeObserver.disconnect();
    scheme.removeEventListener('change', onScheme);
    density.removeEventListener('change', onDensity);
  };
}
